const PSX=(t,q,a,w,s)=>{ let ww=[...new Set(w)].filter(x=>x!==a); if(ww.length<3) ww=ww.concat(["None of these","Cannot be determined","No solution"]).filter(x=>x!==a); return PS(t,q,a,ww.slice(0,3),s); };
const others=(a,pool,n=3)=>shuffle(pool.filter(x=>x!==a)).slice(0,n);
const D2R=Math.PI/180, sinD=x=>Math.sin(x*D2R), cosD=x=>Math.cos(x*D2R), tanD=x=>Math.tan(x*D2R);
const asinD=x=>Math.asin(x)/D2R, acosD=x=>Math.acos(x)/D2R;
const TB=(h,rows)=>`<table class="fq-tb"><tr>${h.map(x=>`<th>${x}</th>`).join("")}</tr>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join("")}</tr>`).join("")}</table>`;

/* exact values */
const pf=(n,d)=>{ if(!n) return "0"; const g=gcd(n,d); n/=g; d/=g; if(d<0){n=-n;d=-d;} const num=n===1?"π":n===-1?"−π":N(n)+"π"; return d===1?num:num+"/"+d; };
const rad=d=>pf(d,180);
const DEG=[0,30,45,60,90,120,135,150,180,210,225,240,270,300,315,330];
const NQ=DEG.filter(d=>d%90);
const norm=d=>((d%360)+360)%360;
const refA=d=>{ d=norm(d); return d<=90?d:d<=180?180-d:d<=270?d-180:360-d; };
const BASE={0:["0","1"],30:["1/2","√3/2"],45:["√2/2","√2/2"],60:["√3/2","1/2"],90:["1","0"]};
const TBASE={0:"0",30:"√3/3",45:"1",60:"√3"};
const neg=s=>s==="0"?"0":s[0]==="−"?s.slice(1):"−"+s;
const sinS=d=>{ const v=BASE[refA(d)][0]; return sinD(d)<-1e-9?neg(v):v; };
const cosS=d=>{ const v=BASE[refA(d)][1]; return cosD(d)<-1e-9?neg(v):v; };
const tanS=d=>{ const r=refA(d); if(r===90) return "Undefined"; const v=TBASE[r]; return sinD(d)*cosD(d)<-1e-9?neg(v):v; };
const RECIP={"0":"Undefined","1":"1","1/2":"2","√3/2":"2√3/3","√2/2":"√2","√3/3":"√3","√3":"√3/3","Undefined":"0"};
const rec=s=>s[0]==="−"?neg(RECIP[s.slice(1)]):RECIP[s];
const SV=["0","1/2","√2/2","√3/2","1","−1/2","−√2/2","−√3/2","−1"], TV=["0","√3/3","1","√3","−√3/3","−1","−√3"];
const QUAD=d=>{ d=norm(d); return d<90?"I":d<180?"II":d<270?"III":"IV"; };
const TRIP=[[3,4,5],[5,12,13],[8,15,17],[7,24,25],[20,21,29],[9,40,41]];
const solveS=(f,v)=>DEG.filter(d=>f(d)===v);
const list=a=>a.length?a.map(rad).join(", "):"No solution";

