 aspd:{grp:"Motion",c:PURP,name:"Linear & Angular Speed",hint:"v = rω",when:"Wheels, gears, rotation.",rule:"Angular speed ω = θ/t (radians per unit time). 1 revolution = 2π rad. Linear speed v = rω = s/t.",ex:[T("30 rev/min",["ω = 30 · 2π = <b>60π rad/min</b>"]),T("r = 2 ft, ω = 10 rad/s",["v = <b>20 ft/s</b>"])]},
