 i0:{grp:"Step 1",c:NAVY,name:"Know the Ranges",hint:"the answer must be in range",when:"Every inverse problem.",rule:"sin⁻¹: [−π/2, π/2]. cos⁻¹: [0, π]. tan⁻¹: (−π/2, π/2). Domain of sin⁻¹ and cos⁻¹ is [−1, 1].",ex:[T("sin⁻¹(−1/2)",["<b>−π/6</b> (not 7π/6)"]),T("cos⁻¹(−1/2)",["<b>2π/3</b>"])]},
 iex:{grp:"Exact",c:ORG,name:"Exact Inverse Values",hint:"unit circle backward",when:"Special values.",rule:"Find the angle in the range whose sin/cos/tan equals the given value.",ex:[T("tan⁻¹(−√3)",["<b>−π/3</b>"]),T("cos⁻¹(√2/2)",["<b>π/4</b>"])]},
