 itri:{grp:"Triangles",c:PURP,name:"Reference-Triangle Compositions",hint:"draw it",when:"cos(tan⁻¹(a/b)) etc.",rule:"Let θ = the inverse; draw a triangle with the given ratio; read the other ratio. Signs from the range of the inverse.",ex:[T("cos(tan⁻¹ 3/4)",["Triangle 3-4-5 ⇒ <b>4/5</b>"]),T("sin(cos⁻¹ x)",["<b>√(1 − x"+sq+")</b>"])]},
 iend:{grp:"Last step",c:GRN,name:"Range Check",hint:"in range?",when:"Every answer.",rule:"An inverse output outside its range is wrong even if the function value matches.",ex:[T("sin⁻¹(1/2) = 5π/6?",["Out of range ⇒ π/6"]),T("cos⁻¹(2)",["No value: 2 ∉ [−1, 1]"])]}
